class Solution {
  public List<String> stringSequence(String target) {
    List<String> res = new ArrayList<>();
    StringBuilder sb = new StringBuilder();
    for (int i = 0; i < target.length(); i++) {
      sb.append('a');
      int last = sb.length() - 1;
      for (char c = 'a'; c <= target.charAt(i); c++) {
        sb.setCharAt(last, c);
        res.add(sb.toString());
      }
    }
    return res;
  }
}
